<div class="body property-layout"><section class="property-main"><h2><?= e($content['property_about'] ?? 'About this property') ?></h2><p class="description"><?= e($property['description'] ?: $property['summary'] ?: '') ?></p><?php if(!empty($propertyAmenities)): ?><h3 class="property-amenities-title">Property amenities</h3><ul class="property-amenities"><?php foreach($propertyAmenities as $amenity): ?><li><?= e($amenity['name']) ?></li><?php endforeach; ?></ul><?php endif; ?><section class="guest-reviews property-reviews"><h2>Guest reviews</h2><p class="muted"><?php if((int)($ratingSummary['rating_count']??0)>0): ?>Average <?= number_format((float)$ratingSummary['rating_average'],1,',','.') ?>/10 · <?= (int)$ratingSummary['rating_count'] ?> verified reviews<?php else: ?>No published reviews for this villa yet.<?php endif; ?></p><?php foreach($reviews as $review): ?><article class="property-review"><strong><?= e($review['username']) ?> · <span style="color:#176b50">★ <?= (int)$review['rating'] ?>/10</span></strong><?php if(trim((string)$review['body'])!==''): ?><p><?= nl2br(e($review['body'])) ?></p><?php endif; ?><small class="muted"><?= e(date('d.m.Y',strtotime($review['created_at']))) ?></small></article><?php endforeach; ?></section></section><aside class="booking property-booking"><strong><?= e(number_format((float)$property['base_nightly_price'],0,',','.')) ?> <?= e($property['currency']) ?> <span class="muted" style="font-size:14px;font-weight:400">/ night</span></strong><p>Contact us to request a reservation and check availability.</p><a href="<?= e(app_url('/villa/' . rawurlencode((string)$property['slug']) . '/reserve')) ?><?= !empty($_GET['check_in'])&&!empty($_GET['check_out'])?'?'.e(http_build_query(['check_in'=>$_GET['check_in'],'check_out'=>$_GET['check_out']])):'' ?>"><?= e($content['property_reserve'] ?? 'Send booking request') ?></a></aside></div></main><script>(function(){var button=document.querySelector(".mobile-menu-toggle"),menu=document.getElementById("siteNavigation");if(!button||!menu)return;function close(){menu.classList.remove("is-open");button.setAttribute("aria-expanded","false");button.setAttribute("aria-label","Open menu");button.textContent="☰"}button.addEventListener("click",function(){var open=menu.classList.toggle("is-open");button.setAttribute("aria-expanded",open?"true":"false");button.setAttribute("aria-label",open?"Close menu":"Open menu");button.textContent=open?"×":"☰"});menu.addEventListener("click",function(e){if(e.target.closest("a"))close()});document.addEventListener("keydown",function(e){if(e.key==="Escape")close()});window.addEventListener("resize",function(){if(window.innerWidth>700)close()})})();var galleryImages=<?= json_encode(array_map(static function(array $image):array{return ['src'=>preg_match('~^https?://~i',(string)$image['file_path'])?$image['file_path']:'/'.ltrim($image['file_path'],'/'),'alt'=>$image['alt_text']?:$property['title']];},$images),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE) ?>;
(function(){var modal=document.getElementById('photoLightbox');if(!modal||!galleryImages.length)return;var image=document.getElementById('lightboxImage'),counter=document.getElementById('lightboxCounter'),index=0,touchX=0,galleryRoot=document.getElementById('propertyGallery'),mobileCounter=document.getElementById('galleryMobileCounter');
function show(n){index=(n+galleryImages.length)%galleryImages.length;image.src=galleryImages[index].src;image.alt=galleryImages[index].alt;counter.textContent=(index+1)+' / '+galleryImages.length}
function open(n){show(n);modal.classList.add('is-open');document.body.style.overflow='hidden';document.getElementById('lightboxClose').focus()}
function close(){modal.classList.remove('is-open');document.body.style.overflow=''}
document.querySelectorAll('[data-gallery-index]').forEach(function(button){button.addEventListener('click',function(){open(Number(button.dataset.galleryIndex))})});
var all=document.getElementById('showAllPhotos');if(all)all.addEventListener('click',function(){open(0)});if(galleryRoot&&mobileCounter){function updateMobileCounter(){var tiles=galleryRoot.querySelectorAll('.gallery-tile');if(!tiles.length)return;var nearest=0,distance=Infinity;tiles.forEach(function(tile,i){var d=Math.abs(tile.offsetLeft-galleryRoot.scrollLeft);if(d<distance){distance=d;nearest=i}});mobileCounter.textContent=(nearest+1)+' / '+galleryImages.length}galleryRoot.addEventListener('scroll',function(){window.requestAnimationFrame(updateMobileCounter)},{passive:true});window.addEventListener('resize',updateMobileCounter);updateMobileCounter()}
document.getElementById('lightboxClose').addEventListener('click',close);document.getElementById('lightboxPrev').addEventListener('click',function(){show(index-1)});document.getElementById('lightboxNext').addEventListener('click',function(){show(index+1)});
modal.addEventListener('click',function(e){if(e.target===modal)close()});document.addEventListener('keydown',function(e){if(!modal.classList.contains('is-open'))return;if(e.key==='Escape')close();if(e.key==='ArrowLeft')show(index-1);if(e.key==='ArrowRight')show(index+1)});
modal.addEventListener('touchstart',function(e){touchX=e.changedTouches[0].screenX},{passive:true});modal.addEventListener('touchend',function(e){var delta=e.changedTouches[0].screenX-touchX;if(Math.abs(delta)>45)show(index+(delta<0?1:-1))},{passive:true});
})();

(function(){var root=document.getElementById('villaAvailability');if(!root)return;var grid=document.getElementById('villaCalendarGrid'),monthLabel=document.getElementById('calendarMonth'),status=document.getElementById('villaCalendarStatus'),selection=document.getElementById('calendarSelectionText'),reserve=document.getElementById('calendarReserve');var now=new Date(),view=new Date(now.getFullYear(),now.getMonth(),1),today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),first=null,last=null,bookings=[],rules=[];var names=['January','February','March','April','May','June','July','August','September','October','November','December'];function iso(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}function parse(s){var p=s.split('-').map(Number);return new Date(p[0],p[1]-1,p[2])}function dayState(d){var key=iso(d);for(var b of bookings)if(key>=b.check_in&&key<b.check_out)return b.status==='confirmed'?'booked':'pending';for(var r of rules)if(key>=r.date_from&&key<r.date_to&&r.status!=='available')return 'blocked';return 'available'}function blocked(d){return d<today||['booked','pending','blocked'].includes(dayState(d))}function render(){grid.innerHTML='';['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].forEach(function(n){var el=document.createElement('div');el.className='calendar-weekday';el.textContent=n;grid.appendChild(el)});var offset=(view.getDay()+6)%7;for(var i=0;i<offset;i++){var empty=document.createElement('div');empty.className='calendar-day empty';grid.appendChild(empty)}var count=new Date(view.getFullYear(),view.getMonth()+1,0).getDate();for(var n=1;n<=count;n++){var d=new Date(view.getFullYear(),view.getMonth(),n),state=dayState(d),key=iso(d),el=document.createElement('button');el.type='button';el.className='calendar-day '+state+(d<today?' past':'');var inRange=first&&last&&key>=first&&key<=last;if(key===first||key===last)el.classList.add('selected');else if(inRange)el.classList.add('in-range');el.disabled=blocked(d);var label=state==='booked'?'Dolu':state==='pending'?'Talep':state==='blocked'?'Blocked':'Available';el.innerHTML='<span class="day-number">'+n+'</span><span class="day-state">'+label+'</span>';el.addEventListener('click',(function(date){return function(){choose(iso(date))}})(d));grid.appendChild(el)}monthLabel.textContent=names[view.getMonth()]+' '+view.getFullYear()}function choose(key){if(!first||last||key<=first){first=key;last=null}else{last=key}if(first&&last){var start=parse(first),end=parse(last),bad=false;for(var d=new Date(start);d<end;d.setDate(d.getDate()+1)){if(blocked(d)){bad=true;break}}if(bad){last=null;status.textContent='Your selected range includes booked or blocked dates. Choose another check-out date.'}else{status.textContent='Checking price and availability…';var u=new URL(root.dataset.priceUrl,location.origin);u.searchParams.set('check_in',first);u.searchParams.set('check_out',last);u.searchParams.set('guests','1');fetch(u,{headers:{Accept:'application/json'}}).then(r=>r.json()).then(data=>{if(data.ok){status.textContent=data.nights+' night · Total '+new Intl.NumberFormat(<?= json_encode(\App\Core\Translator::locale(), JSON_UNESCAPED_SLASHES) ?>,{style:'currency',currency:data.currency}).format(data.total)+' · Available';reserve.href=root.dataset.reserveUrl+'?'+new URLSearchParams({check_in:first,check_out:last}).toString();reserve.setAttribute('aria-disabled','false')}else{last=null;status.textContent=data.message||'These dates are unavailable.';reserve.href='#';reserve.setAttribute('aria-disabled','true')}renderSelection();render()}).catch(()=>{status.textContent='Availability could not be verified. Please try again.';last=null;renderSelection();render()})}}else{status.textContent='Now select your check-out date.';reserve.href='#';reserve.setAttribute('aria-disabled','true')}renderSelection();render()}function renderSelection(){selection.textContent=first?(last?'Check-in: '+first+' · Check-out: '+last:'Check-in: '+first+' · Select check-out date'):'Select your check-in and check-out dates on the calendar.'}function load(){var m=view.getFullYear()+'-'+String(view.getMonth()+1).padStart(2,'0');status.textContent='Loading availability…';fetch(root.dataset.calendarUrl+'?month='+m,{headers:{Accept:'application/json'}}).then(r=>r.json()).then(data=>{if(!data.ok)throw new Error(data.message||'Calendar could not be loaded');bookings=data.bookings||[];rules=data.rules||[];status.textContent='Calendar reflects current bookings and blocked dates.';render()}).catch(()=>{status.textContent='Calendar data could not be retrieved. Please refresh the page.';grid.innerHTML='';render()})}document.getElementById('calendarPrev').addEventListener('click',function(){view.setMonth(view.getMonth()-1);load()});document.getElementById('calendarNext').addEventListener('click',function(){view.setMonth(view.getMonth()+1);load()});load()})();
</script><script>(function(){document.querySelectorAll('.js-favorite-form').forEach(function(form){form.addEventListener('submit',async function(event){event.preventDefault();var button=form.querySelector('button[type="submit"]');if(!button||button.disabled)return;var oldText=button.textContent;button.disabled=true;try{var response=await fetch(form.action,{method:'POST',body:new FormData(form),credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});var data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||'Favorite action could not be completed.');button.classList.toggle('is-active',!!data.active);button.setAttribute('aria-pressed',data.active?'true':'false');button.textContent=data.active?'♥ Remove from favorites':'♡ Add to favorites';var status=document.getElementById('favoriteActionStatus');if(!status){status=document.createElement('div');status.id='favoriteActionStatus';status.setAttribute('role','status');status.setAttribute('aria-live','polite');status.style.cssText='position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:6000;padding:11px 16px;border-radius:999px;background:#20352e;color:#fff;font:600 13px system-ui;box-shadow:0 8px 24px #0002';document.body.appendChild(status)}status.textContent=data.message;status.hidden=false;clearTimeout(status._hideTimer);status._hideTimer=setTimeout(function(){status.hidden=true},2400)}catch(error){button.textContent=oldText;window.alert(error.message||'An error occurred while updating favorites.')}finally{button.disabled=false}})})})();</script><?php require APP_ROOT.'/views/site/partials/login-modal.php'; ?></body></html>